// PricePulse MAILER V3 (13 Nov 2026) - one Edge Function for all PricePulse emails, one locked design (claude/EMAIL-PLAN.md).
//   1) price alerts waiting in pp_deal_alert_notifications (as before)
//   2) weekly price email on Sunday after 10:00 IST (opt-in; moved here from alerts-extra)
//   3) everything in pp_email_queue: welcome, upgrade, support auto-reply, receipt, renew, expired, support reply
//   GET/POST ?unsub=<token>  -> one-click unsubscribe from marketing mails (weekly + upgrade)
// Needs supabase-emails-v1.sql. Login code (OTP) mail is a Supabase Auth template, not sent from here.
// Secrets (Supabase > Edge Functions > Secrets). Never put keys in chat or code:
//   BREVO_API_KEY    (required)
//   ALERT_FROM       (required)  PricePulse <no-reply@price-pulse.in>
//   MARKETING_FROM   (optional)  PricePulse <hello@price-pulse.in>    weekly + upgrade   (falls back to ALERT_FROM)
//   SUPPORT_FROM     (optional)  PricePulse Support <support@price-pulse.in>             (falls back to ALERT_FROM)
//   SITE_URL         (optional)  default https://price-pulse.in
// Deploy with "Verify JWT" OFF (cron + unsubscribe links call it). A mail is sent once.
// Test without sending: .../functions/v1/send-deal-alerts?dry=1
import postgres from "npm:postgres@3.4.4";

// RENDER-START
type Any = any;
type Mail = { subject: string; html: string; text: string };
const LINKS = {
  telegram: "https://t.me/pricepulsealerts",
  instagram: "https://www.instagram.com/pricepulseindia",
  whatsapp: "https://whatsapp.com/channel/0029Vb99ErHLdQejMXVhxi0q",
};
const SUPPORT = "support@price-pulse.in";
const esc = (s: unknown) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" } as Any)[c]);
const inr = (n: unknown) => "₹" + Number(n).toLocaleString("en-IN", { maximumFractionDigits: 0 });
const okUrl = (u: unknown): u is string => typeof u === "string" && /^https:\/\/[^\s"'<>]+$/.test(u.trim());
const day = (d: unknown) => {
  const t = new Date(String(d));
  return isNaN(t.getTime()) ? "" : t.toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric", timeZone: "Asia/Kolkata" });
};
const parseFrom = (v: string) => {
  const m = v.match(/^\s*(?:"?([^"<]*?)"?\s*)?<([^>]+)>\s*$/);
  return m ? { name: (m[1] || "PricePulse").trim() || "PricePulse", email: m[2].trim() } : { name: "PricePulse", email: v.trim() };
};
// long store titles -> short name
const shortName = (s: unknown) => {
  let t = String(s || "Product").replace(/\s+/g, " ").trim();
  const cut = t.search(/\s[|(\[]|,|\s[-–]\s/);
  if (cut > 12) t = t.slice(0, cut).trim();
  if (t.length > 70) t = t.slice(0, 67).replace(/\s+\S*$/, "") + "...";
  return t;
};
const FONT = "font-family:Arial,Helvetica,sans-serif;";
// Header logo + Telegram icon are served by this function itself (?img=logo / ?img=tg) - nothing to host on the site.
// Images are not colour-inverted by Gmail dark mode, so the logo stays readable.
const IMG_BASE = "https://akdrydxbvdtadmcphhxj.supabase.co/functions/v1/send-deal-alerts";
const img = (k: string) => `https://price-pulse.in/mail/${k}.png?v=6`; // static files on the site (fast, own domain); ?img= endpoint below stays as a fallback

// ---------- shared pieces ----------
function footerHtml(links: Any, reason: string, unsubUrl = "") {
  const ext = okUrl(links.extension_url) ? links.extension_url.trim() : "";
  const app = okUrl(links.app_url) ? links.app_url.trim() : "";
  const cell = (href: string, bg: string, color: string, border: string, title: string, sub: string, subColor: string) => {
    const inner = `<span style="display:block;font-size:13px;font-weight:700;color:${color}">${title}</span><span style="display:block;font-size:10px;font-weight:700;color:${subColor};letter-spacing:.3px">${sub}</span>`;
    const box = `background:${bg};border:1px solid ${border};border-radius:10px;padding:9px 4px;text-align:center;${FONT}`;
    return href
      ? `<td style="padding:0 4px" width="33%"><a href="${esc(href)}" style="display:block;text-decoration:none;${box}">${inner}</a></td>`
      : `<td style="padding:0 4px" width="33%"><div style="${box}">${inner}</div></td>`;
  };
  const row1 = cell(LINKS.telegram, "#229ED9", "#ffffff", "#229ED9", `<img src="${img("tg")}" width="16" height="16" alt="" style="vertical-align:-3px;margin-right:5px;border:0">Telegram`, "FREE ALERTS", "#d7efff")
    + (ext ? cell(ext, "#ffffff", "#10211B", "#ffffff", "Extension", "ADD TO CHROME", "#13805A") : cell("", "#10211B", "#ffffff", "#2c4a3d", "Extension", "COMING SOON", "#E8B954"))
    + (app ? cell(app, "#ffffff", "#10211B", "#ffffff", "App", "GET THE APP", "#13805A") : cell("", "#10211B", "#ffffff", "#2c4a3d", "App", "COMING SOON", "#E8B954"));
  const btn2 = (href: string, bg: string, color: string, label: string) => `<td style="padding:0 4px" width="50%"><a href="${href}" style="display:block;text-decoration:none;background:${bg};color:${color};border-radius:10px;padding:10px 4px;text-align:center;font-size:13px;font-weight:700;${FONT}">${label}</a></td>`;
  const row2 = btn2(LINKS.instagram, "#C13584", "#ffffff", "Instagram") + btn2(LINKS.whatsapp, "#25D366", "#0c1a15", "WhatsApp");
  const unsub = unsubUrl ? ` <a href="${esc(unsubUrl)}" style="color:#8fa89b;text-decoration:underline">Unsubscribe</a>` : "";
  return `<tr><td style="background:#0c1a15;padding:18px 18px 16px;border-radius:0 0 14px 14px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>${row1}</tr></table>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:8px"><tr>${row2}</tr></table>
<p style="margin:14px 0 0;text-align:center;font-size:11px;line-height:1.6;color:#8fa89b;${FONT}"><a href="https://price-pulse.in" style="color:#8fa89b;text-decoration:none">price-pulse.in</a> : <a href="mailto:${SUPPORT}" style="color:#8fa89b;text-decoration:none">${SUPPORT}</a><br>${reason}${unsub}</p>
</td></tr>`;
}
function smallFooter(reason: string) {
  return `<tr><td style="background:#0c1a15;padding:14px 18px;border-radius:0 0 14px 14px"><p style="margin:0;text-align:center;font-size:11px;line-height:1.6;color:#8fa89b;${FONT}"><a href="https://price-pulse.in" style="color:#8fa89b;text-decoration:none">price-pulse.in</a> : <a href="mailto:${SUPPORT}" style="color:#8fa89b;text-decoration:none">${SUPPORT}</a><br>${reason}</p></td></tr>`;
}
function layout({ preheader, headSub, body, footer }: { preheader: string; headSub: string; body: string; footer: string }) {
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>PricePulse</title></head>
<body style="margin:0;padding:0;background:#E9EEEB">
<div style="display:none;max-height:0;overflow:hidden;opacity:0">${esc(preheader)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#E9EEEB"><tr><td align="center" style="padding:20px 10px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:520px;background:#ffffff;border-radius:14px">
<tr><td style="background:#10211B;background-image:linear-gradient(180deg,#10211B,#0D1D17);padding:14px 20px;border-bottom:3px solid #E8B954;border-radius:14px 14px 0 0;${FONT}">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
<td valign="middle" width="206" style="width:206px"><img src="${img("logo")}" width="200" height="42" alt="PricePulse - Right Price, Right Choice" style="display:block;border:0;font-size:18px;font-weight:700;color:#ffffff"></td>
</tr></table></td></tr>
<tr><td style="padding:20px 22px 22px;${FONT}color:#10211B"><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 14px"><tr><td style="background:#e3f5ec;border-radius:99px;padding:5px 12px 5px 10px;font-size:10px;font-weight:700;letter-spacing:.9px;white-space:nowrap;color:#13805A;${FONT}"><span style="color:#E8B954;font-size:12px">&#9679;</span>&nbsp; ${esc(headSub.toUpperCase())}</td></tr></table>${body}</td></tr>
${footer}
</table></td></tr></table></body></html>`;
}
const h1 = (t: string) => `<p style="margin:0 0 10px;font-size:20px;font-weight:800;line-height:1.3;color:#10211B">${t}</p>`;
const p = (t: string) => `<p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#33443c">${t}</p>`;
const note = (t: string) => `<p style="margin:0;font-size:12px;line-height:1.6;color:#5b6b63">${t}</p>`;
const button = (href: string, label: string) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:18px 0"><tr><td align="center" style="background:#E8B954;border-radius:12px"><a href="${esc(href)}" style="display:block;padding:14px;font-size:15px;font-weight:700;color:#10211B;text-decoration:none;${FONT}">${label}</a></td></tr></table>`;
const box = (inner: string) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f7faf8;border:1px solid #e3ebe7;border-radius:14px;margin:0 0 4px"><tr><td style="padding:14px 16px;${FONT}">${inner}</td></tr></table>`;
const tick = (t: string) => `<tr><td width="24" valign="top" style="padding:5px 0;color:#13805A;font-weight:800;font-size:14px;${FONT}">&#10003;</td><td style="padding:5px 0;font-size:14px;line-height:1.5;color:#10211B;${FONT}">${t}</td></tr>`;
const ticks = (rows: string[]) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">${rows.map(tick).join("")}</table>`;
const kv = (rows: [string, string][]) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">${rows.map(([k, v]) => `<tr><td style="padding:6px 0;font-size:13px;color:#5b6b63;border-bottom:1px solid #e3ebe7;${FONT}">${k}</td><td align="right" style="padding:6px 0;font-size:13px;font-weight:700;color:#10211B;border-bottom:1px solid #e3ebe7;${FONT}">${v}</td></tr>`).join("")}</table>`;
const plain = (...lines: string[]) => lines.filter((x) => x !== undefined).join("\n") + `\n\nPricePulse - https://price-pulse.in\nTelegram (free alerts): ${LINKS.telegram}\nInstagram: ${LINKS.instagram}\nWhatsApp: ${LINKS.whatsapp}`;

// ---------- 2) price alert ----------
function renderAlert(r: Any, site: string, links: Any): Mail {
  const name = shortName(r.product_name);
  const price = Number(r.trigger_price), target = Number(r.target_price);
  const mrp = Number(r.mrp);
  const link = `${site}/#/product/${encodeURIComponent(r.product_id)}`; // PricePulse product page (best deal there), never the store link
  const img = okUrl(r.product_image) ? String(r.product_image).trim() : "";
  const store = r.retailer ? String(r.retailer) : "";
  const gap = target - price;
  const gapLine = gap > 0 ? `That is ${inr(gap)} below your target.` : "That is exactly your target.";
  const chip = (t: string) => `<span style="display:inline-block;background:#e3f5ec;color:#13805A;font-weight:700;font-size:11px;padding:3px 9px;border-radius:99px;margin:4px 4px 0 0">${t}</span>`;
  const mrpHtml = Number.isFinite(mrp) && mrp > price
    ? ` <span style="font-size:13px;color:#7E8C84;text-decoration:line-through">${inr(mrp)}</span> <span style="display:inline-block;background:#13805A;color:#fff;font-size:11px;font-weight:700;padding:3px 10px;border-radius:99px;vertical-align:middle">${inr(mrp - price)} below MRP</span>` : "";
  const imgCell = img ? `<td width="88" valign="middle" style="padding-right:14px"><img src="${esc(img)}" width="80" height="80" alt="" style="display:block;width:80px;height:80px;object-fit:contain;border-radius:10px;background:#fff;border:1px solid #e3ebe7"></td>` : "";
  const body = `
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f7faf8;border:1px solid #e3ebe7;border-radius:14px"><tr><td style="padding:14px"><table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>${imgCell}
<td valign="middle" style="${FONT}"><div style="font-size:15px;font-weight:700;line-height:1.35;color:#10211B">${esc(name)}</div>${store ? chip(esc(store)) : ""}${chip("Your target " + inr(target))}</td></tr></table></td></tr></table>
<div style="margin-top:16px"><span style="font-size:32px;font-weight:800;color:#13805A">${inr(price)}</span>${mrpHtml}</div>
<p style="margin:6px 0 0;font-size:13px;color:#5b6b63">${gapLine}</p>
${button(link, "See the price on PricePulse")}
${note(`Prices can change at any time. You get this email once per alert. <a href="${site}/#/alerts" style="color:#13805A">Manage alerts</a>`)}`;
  const html = layout({ preheader: `${name} is now ${inr(price)}${store ? " at " + store : ""}. Your target was ${inr(target)}.`, headSub: "Your price target was reached", body, footer: footerHtml(links, "You are receiving this because you set a price alert on PricePulse.") });
  return { subject: `Price alert: ${name} is now ${inr(price)}`, html, text: plain("Your price target was reached.", name, `Now ${inr(price)}${store ? " at " + store : ""} (your target ${inr(target)})`, link, "", `Prices can change at any time. Manage alerts: ${site}/#/alerts`) };
}

// ---------- 3) welcome ----------
function renderWelcome(_d: Any, site: string, links: Any): Mail {
  const body = h1("Welcome to PricePulse")
    + p("Your account is ready. Here is how to pay the right price, every time:")
    + ticks([
      "<b>Set a price alert</b> on any product. We email you when it reaches your target.",
      "<b>Compare stores</b> side by side before you buy.",
      "<b>Check the price history</b> to see if a deal is really a deal.",
    ])
    + button(`${site}/#/deals`, "See today's deals")
    + note(`Free plan: 3 price alerts. Need more? <a href="${site}/#/plus" style="color:#13805A">PricePulse Plus</a> gives you 12.`);
  return {
    subject: "Welcome to PricePulse",
    html: layout({ preheader: "Your account is ready. Set your first price alert.", headSub: "Right Price, Right Choice", body, footer: footerHtml(links, "You are receiving this because you created a PricePulse account.") }),
    text: plain("Welcome to PricePulse", "Your account is ready.", "- Set a price alert: we email you when it reaches your target.", "- Compare stores side by side.", "- Check the price history.", "", `Today's deals: ${site}/#/deals`),
  };
}

// ---------- 4) weekly ----------
function renderWeekly(d: Any, site: string, links: Any, unsubUrl: string): Mail {
  const items: Any[] = Array.isArray(d.items) ? d.items : [];
  const rows = items.map((x) => {
    const now = x.now == null ? null : Number(x.now), week = x.week == null ? null : Number(x.week);
    const diff = now != null && week != null ? now - week : null;
    const change = diff == null ? "" : diff < 0
      ? `<span style="display:inline-block;background:#e3f5ec;color:#13805A;font-weight:700;font-size:11px;padding:2px 8px;border-radius:99px">&#9660; ${inr(-diff)} this week</span>`
      : diff > 0 ? `<span style="display:inline-block;background:#fdf1e6;color:#b45309;font-weight:700;font-size:11px;padding:2px 8px;border-radius:99px">&#9650; ${inr(diff)} this week</span>`
      : `<span style="font-size:11px;color:#7E8C84">Same as last week</span>`;
    const href = `${site}/#/product/${encodeURIComponent(String(x.product_id))}`;
    return `<tr><td style="padding:12px 0;border-bottom:1px solid #e3ebe7;${FONT}"><a href="${esc(href)}" style="font-size:14px;font-weight:700;color:#10211B;text-decoration:none">${esc(shortName(x.name))}</a><br>`
      + (now != null ? `<span style="font-size:16px;font-weight:800;color:#13805A">${inr(now)}</span> <span style="font-size:12px;color:#5b6b63">at ${esc(x.retailer)}</span> ${change}` : `<span style="font-size:12px;color:#7E8C84">No verified price right now</span>`)
      + `</td></tr>`;
  }).join("");
  const body = h1("Your products this week")
    + p("Prices of the products in your wishlist and alerts, compared with last week.")
    + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">${rows}</table>`
    + button(`${site}/#/alerts`, "Open My Alerts")
    + note("Prices can change at any time. Store links may earn us a commission.");
  return {
    subject: "Your weekly PricePulse prices",
    html: layout({ preheader: `${items.length} product${items.length === 1 ? "" : "s"} you follow, this week's prices.`, headSub: "Weekly price email", body, footer: footerHtml(links, "You are receiving this because you switched on the weekly price email.", unsubUrl) }),
    text: plain("Your products this week", ...items.map((x) => `${shortName(x.name)}: ${x.now != null ? inr(x.now) + " at " + x.retailer : "no verified price now"}`), "", `My Alerts: ${site}/#/alerts`, unsubUrl ? `Unsubscribe: ${unsubUrl}` : ""),
  };
}

// ---------- 5) upgrade ----------
function renderUpgrade(d: Any, site: string, links: Any, unsubUrl: string): Mail {
  const lim = Number(d.limit) || 3;
  const plan = (name: string, price: string, lines: string[], best = false) => `<td width="50%" valign="top" style="padding:0 4px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:${best ? "2px solid #E8B954" : "1px solid #e3ebe7"};border-radius:12px;background:${best ? "#fffaf0" : "#f7faf8"}"><tr><td style="padding:14px 12px;${FONT}">`
    + (best ? `<span style="display:inline-block;background:#E8B954;color:#10211B;font-size:10px;font-weight:800;padding:2px 8px;border-radius:99px;margin-bottom:6px">BEST VALUE</span><br>` : "")
    + `<span style="font-size:14px;font-weight:800;color:#10211B">${name}</span><br><span style="font-size:22px;font-weight:800;color:#13805A">${price}</span>`
    + lines.map((l) => `<br><span style="font-size:12px;line-height:1.7;color:#33443c">&#10003; ${l}</span>`).join("") + `</td></tr></table></td>`;
  const body = h1(`You are using all ${lim} free alerts`)
    + p("Good choice watching prices! To track more products, pick a plan:")
    + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:4px 0 0"><tr>`
    + plan("Plus", "₹99 / year", ["12 price alerts", "Valid for 1 year"])
    + plan("Plus + Pro", "₹199", ["Plus for 1 year", "Pro for 3 months", "Unlimited alerts with Pro"], true)
    + `</tr></table>`
    + button(`${site}/#/plus`, "See plans")
    + note("Your current alerts keep working on the Free plan. This is a one-time email.");
  return {
    subject: `You are using all ${lim} free price alerts`,
    html: layout({ preheader: "Track more products with PricePulse Plus.", headSub: "Track more products", body, footer: footerHtml(links, "You are receiving this because you use price alerts on PricePulse.", unsubUrl) }),
    text: plain(`You are using all ${lim} free alerts.`, "Plus: ₹99 / year, 12 price alerts.", "Plus + Pro: ₹199, Plus for 1 year + Pro for 3 months (unlimited alerts with Pro).", `See plans: ${site}/#/plus`, unsubUrl ? `Unsubscribe: ${unsubUrl}` : ""),
  };
}

// ---------- 6) support auto-reply ----------
function renderAutoreply(d: Any, site: string): Mail {
  const subj = String(d.subject || "").slice(0, 120);
  const body = h1("We got your message")
    + p("Thanks for writing to PricePulse support. A real person reads every message and we usually reply within 1 to 2 working days.")
    + (subj ? box(`<span style="font-size:11px;color:#7E8C84">Your message</span><br><span style="font-size:14px;font-weight:700;color:#10211B">${esc(subj)}</span>`) : "")
    + p(`While you wait, you can check <a href="${site}/#/help" style="color:#13805A">Help</a> or manage your <a href="${site}/#/alerts" style="color:#13805A">price alerts</a>.`)
    + note("No need to reply to this email. To add details, just reply to your first email.");
  return {
    subject: subj ? `Re: ${subj}` : "We got your message",
    html: layout({ preheader: "Thanks for writing to PricePulse support.", headSub: "PricePulse Support", body, footer: smallFooter("This is an automatic reply to your email to PricePulse support.") }),
    text: `We got your message.\nThanks for writing to PricePulse support. A real person reads every message and we usually reply within 1 to 2 working days.\n\nHelp: ${site}/#/help\n\nPricePulse - https://price-pulse.in`,
  };
}

// ---------- 7) receipt ----------
function renderReceipt(d: Any, site: string, links: Any): Mail {
  const rows: [string, string][] = [["Plan", esc(d.plan || "PricePulse Plus")], ["Amount paid", inr(d.amount)], ["Date", day(d.paid_at)]];
  if (d.valid_until) rows.push(["Plus valid until", day(d.valid_until)]);
  if (d.pro_until) rows.push(["Pro valid until", day(d.pro_until)]);
  if (d.ref) rows.push(["Payment ID", esc(d.ref)]);
  const body = h1("Payment received, thank you!")
    + p(`Your ${esc(d.plan || "PricePulse Plus")} is now active.`)
    + box(kv(rows))
    + button(`${site}/#/account`, "Go to my account")
    + note(`Keep this email as your receipt. Questions about this payment? Write to <a href="mailto:${SUPPORT}" style="color:#13805A">${SUPPORT}</a>.`);
  return {
    subject: `Your PricePulse receipt: ${String(d.plan || "Plus")} ${inr(d.amount)}`,
    html: layout({ preheader: `Payment of ${inr(d.amount)} received. Your plan is active.`, headSub: "Payment receipt", body, footer: footerHtml(links, "You are receiving this because you made a payment on PricePulse.") }),
    text: plain("Payment received, thank you!", ...rows.map(([k, v]) => `${k}: ${v.replace(/&amp;/g, "&")}`), "", `My account: ${site}/#/account`),
  };
}

// ---------- 8) renew reminder ----------
function renderRenew(d: Any, site: string, links: Any): Mail {
  const left = Math.max(1, Number(d.days_left) || 1);
  const when = day(d.expires_at);
  const body = h1(`Your Plus ends in ${left} day${left === 1 ? "" : "s"}`)
    + p(`Your PricePulse Plus is active until <b>${when}</b>. Renew now and the new year is added after this date, so you lose no days.`)
    + box(ticks(["<b>Renew Plus</b> for 1 more year: ₹99", "<b>Renew Plus + Pro</b> (3 months Pro): ₹199"]))
    + button(`${site}/#/plus`, "Renew my Plus")
    + note("If you do not renew, your account moves to the Free plan (3 alerts). Your alerts stay saved.");
  return {
    subject: `Your PricePulse Plus ends on ${when}`,
    html: layout({ preheader: `Renew before ${when} and keep your 12 alerts.`, headSub: "Plus renewal reminder", body, footer: footerHtml(links, "You are receiving this because you have a PricePulse Plus membership.") }),
    text: plain(`Your PricePulse Plus ends on ${when} (${left} days left).`, "Renew Plus for 1 more year: ₹99", "Renew Plus + Pro (3 months Pro): ₹199", `Renew: ${site}/#/plus`),
  };
}

// ---------- 9) expired ----------
function renderExpired(d: Any, site: string, links: Any): Mail {
  const isPro = String(d.plan) === "Pro";
  const body = h1(isPro ? "Your Pro has ended" : "Your Plus has ended")
    + p(isPro
      ? `Your Pro ended on <b>${day(d.ended_at)}</b>. You are still on Plus with 12 price alerts.`
      : `Your PricePulse Plus ended on <b>${day(d.ended_at)}</b>. Your account is now on the Free plan with 3 price alerts.`)
    + p(isPro ? "Your saved alerts are not deleted." : "Your saved alerts are not deleted. To add more than 3 alerts, get Plus again.")
    + button(`${site}/#/plus`, isPro ? "Get Pro again" : "Get Plus again")
    + note(isPro ? "Pro for 1 month: ₹99 (needs active Plus)." : "Plus: ₹99 / year, 12 price alerts.");
  return {
    subject: isPro ? "Your PricePulse Pro has ended" : "Your PricePulse Plus has ended",
    html: layout({ preheader: isPro ? "You are still on Plus." : "Your account is now on the Free plan.", headSub: isPro ? "Pro ended" : "Plus ended", body, footer: footerHtml(links, "You are receiving this because you have a PricePulse Plus membership.") }),
    text: plain(isPro ? `Your Pro ended on ${day(d.ended_at)}. You are still on Plus.` : `Your PricePulse Plus ended on ${day(d.ended_at)}. You are now on the Free plan (3 alerts).`, "Your saved alerts are not deleted.", `Plans: ${site}/#/plus`),
  };
}

// ---------- 10) support reply (your own text) ----------
function renderSupportReply(d: Any, _site: string, links: Any): Mail {
  const subj = String(d.subject || "Your message to PricePulse").slice(0, 150);
  const msg = esc(String(d.message || "")).replace(/\r?\n/g, "<br>");
  const body = `<div style="font-size:14px;line-height:1.7;color:#10211B">${msg}</div>`
    + `<p style="margin:18px 0 0;font-size:12px;line-height:1.6;color:#5b6b63">Just reply to this email if you need anything else.</p>`;
  return {
    subject: subj.startsWith("Re:") ? subj : `Re: ${subj}`,
    html: layout({ preheader: String(d.message || "").slice(0, 90), headSub: "PricePulse Support", body, footer: footerHtml(links, "You are receiving this because you wrote to PricePulse support.") }),
    text: `${String(d.message || "")}\n\nJust reply to this email if you need anything else.\nPricePulse Support - ${SUPPORT}`,
  };
}

const MARKETING = new Set(["weekly", "upgrade"]);
const SUPPORT_TYPES = new Set(["support_autoreply", "support_reply"]);
function renderQueued(type: string, d: Any, site: string, links: Any, unsubUrl: string): Mail | null {
  switch (type) {
    case "welcome": return renderWelcome(d, site, links);
    case "weekly": return renderWeekly(d, site, links, unsubUrl);
    case "upgrade": return renderUpgrade(d, site, links, unsubUrl);
    case "support_autoreply": return renderAutoreply(d, site);
    case "receipt": return renderReceipt(d, site, links);
    case "renew": return renderRenew(d, site, links);
    case "expired": return renderExpired(d, site, links);
    case "support_reply": return renderSupportReply(d, site, links);
  }
  return null;
}
export { renderAlert, renderQueued };
// RENDER-END

// PNG data for the two mail images (served at ?img=logo and ?img=tg)
const MAIL_IMAGES: Record<string, string> = {
  logo: "",
  tg: "",
};

function isDigestTime(d: Date) {
  const ist = new Date(d.getTime() + 5.5 * 3600e3);
  return ist.getUTCDay() === 0 && ist.getUTCHours() >= 10;
}
const page = (title: string, msg: string) => new Response(`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PricePulse</title></head><body style="margin:0;background:#E9EEEB;${FONT}"><div style="max-width:420px;margin:40px auto;background:#fff;border-radius:14px;overflow:hidden"><div style="background:#10211B;padding:16px 20px;border-bottom:3px solid #E8B954;font-size:20px;font-weight:700;color:#fff">Price<span style="color:#18D49D">Pulse</span></div><div style="padding:22px;color:#10211B"><p style="margin:0 0 8px;font-size:18px;font-weight:800">${title}</p><p style="margin:0 0 16px;font-size:14px;line-height:1.6;color:#33443c">${msg}</p><a href="https://price-pulse.in" style="color:#13805A;font-weight:700">Go to price-pulse.in</a></div></div></body></html>`, { headers: { "Content-Type": "text/html; charset=utf-8" } });

if (typeof Deno !== "undefined") Deno.serve(async (req: Request) => {
  const url = new URL(req.url);
  const dbUrl = Deno.env.get("SUPABASE_DB_URL");
  if (!dbUrl) return new Response(JSON.stringify({ error: "SUPABASE_DB_URL missing" }), { status: 500 });

  // mail images (header logo, Telegram icon)
  const imgKey = url.searchParams.get("img");
  if (imgKey !== null) {
    const b64 = MAIL_IMAGES[imgKey];
    if (!b64) return new Response("not found", { status: 404 });
    const bin = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
    return new Response(bin, { headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=604800" } });
  }

  // one-click unsubscribe (link in the mail + List-Unsubscribe header)
  const unsub = url.searchParams.get("unsub");
  if (unsub !== null) {
    if (!/^[0-9a-f-]{36}$/i.test(unsub)) return page("Link not valid", "This unsubscribe link is not valid.");
    const s = postgres(dbUrl, { max: 1, prepare: false });
    try {
      const r = await s`select public.pp_email_unsubscribe(${unsub}::uuid) as ok`;
      return r[0]?.ok ? page("You are unsubscribed", "You will not get the weekly price email or offer emails any more. Price alerts you set still arrive by email.") : page("Link not valid", "This unsubscribe link is not valid or has expired.");
    } finally { await s.end({ timeout: 2 }); }
  }

  const dry = url.searchParams.get("dry") === "1";
  const key = Deno.env.get("BREVO_API_KEY");
  const fromAlert = Deno.env.get("ALERT_FROM") || "";
  const fromMkt = Deno.env.get("MARKETING_FROM") || fromAlert;
  const fromSupport = Deno.env.get("SUPPORT_FROM") || fromAlert;
  const site = (Deno.env.get("SITE_URL") || "https://price-pulse.in").replace(/\/+$/, "");
  const self = `${(Deno.env.get("SUPABASE_URL") || url.origin).replace(/\/+$/, "")}/functions/v1/send-deal-alerts`;
  if (!dry && (!key || !fromAlert)) return new Response(JSON.stringify({ error: "Set BREVO_API_KEY and ALERT_FROM in Edge Function secrets" }), { status: 500 });

  const send = async (from: string, to: string, m: Mail, tag: string, extra: Any = {}) => {
    const res = await fetch("https://api.brevo.com/v3/smtp/email", {
      method: "POST",
      headers: { "api-key": String(key), "Content-Type": "application/json", accept: "application/json" },
      body: JSON.stringify({ sender: parseFrom(from), to: [{ email: to }], subject: m.subject, htmlContent: m.html, textContent: m.text, tags: [tag], ...extra }),
    });
    const body: Any = await res.json().catch(() => ({}));
    return res.ok && body.messageId ? { ok: true, id: String(body.messageId) } : { ok: false, err: String(body.message || body.code || res.status).slice(0, 300) };
  };

  const sql = postgres(dbUrl, { max: 1, prepare: false });
  const out: Any = { dry, alerts: 0, weekly_queued: 0, queue: 0, sent: 0, failed: 0, skipped: 0 };
  try {
    const st = await sql`select to_jsonb(s) as j from public.pp_alert_delivery_settings s where s.id = true limit 1`;
    const links = (st[0] && st[0].j) || {};
    const types = Object.fromEntries((await sql`select type, enabled from public.pp_email_types`).map((t: Any) => [t.type, t.enabled]));

    // 1) price alerts
    const rows = await sql`
      select n.id, n.email_to, n.product_id, n.product_name, n.target_price, n.trigger_price, n.retailer,
             a.ext_url, a.product_image,
             (select to_jsonb(p) ->> 'mrp' from public.pp_retailer_prices p
               where p.product_id = n.product_id and p.retailer = n.retailer limit 1) as mrp
      from public.pp_deal_alert_notifications n
      left join public.pp_deal_alerts a on a.id = n.alert_id
      where n.status = 'pending' order by n.created_at limit 25`;
    out.alerts = rows.length;
    for (const r of rows) {
      const m = renderAlert(r, site, links);
      if (dry) continue;
      try {
        const s = await send(fromAlert, r.email_to, m, "price-alert");
        if (s.ok) { await sql`update public.pp_deal_alert_notifications set status = 'sent', sent_at = now(), provider_message_id = ${s.id!}, error_message = null where id = ${r.id}`; out.sent++; }
        else { await sql`update public.pp_deal_alert_notifications set status = 'failed', error_message = ${s.err!} where id = ${r.id}`; out.failed++; }
      } catch (e) {
        await sql`update public.pp_deal_alert_notifications set status = 'failed', error_message = ${String(e).slice(0, 300)} where id = ${r.id}`; out.failed++;
      }
    }

    // 2) weekly price email -> queue (Sunday after 10:00 IST, opt-in, not unsubscribed)
    if (types.weekly && isDigestTime(new Date()) && !dry) {
      const users = await sql`select o.user_id, o.email from public.pp_digest_optin o
        left join public.pp_email_prefs e on e.user_id = o.user_id
        where o.enabled and coalesce(o.email, '') <> '' and not coalesce(e.marketing_off, false)
          and (o.last_sent is null or o.last_sent < now() - interval '6 days') limit 50`;
      for (const u of users) {
        const ids = (await sql`select product_id from public.wishlist_items where user_id = ${u.user_id} union select product_id from public.pp_deal_alerts where user_id = ${u.user_id} limit 15`).map((x: Any) => x.product_id);
        await sql`update public.pp_digest_optin set last_sent = now() where user_id = ${u.user_id}`;
        if (!ids.length) continue;
        const now = await sql`select * from public.pp_best_now(${ids})`;
        const week = await sql`select product_id, min(price) p from public.pp_retailer_price_history where product_id = any(${ids}) and availability = 'in_stock' and checked_at between now() - interval '8 days' and now() - interval '6 days' group by 1`;
        const names = await sql`select product_id, name from public.pp_catalog_products where product_id = any(${ids})`;
        const items = ids.map((id: string) => {
          const n: Any = now.find((x: Any) => x.product_id === id), w: Any = week.find((x: Any) => x.product_id === id);
          return { product_id: id, name: names.find((x: Any) => x.product_id === id)?.name || id, now: n ? Number(n.price) : null, retailer: n?.retailer || null, week: w ? Number(w.p) : null };
        });
        const q = await sql`select public.pp_email_enqueue('weekly', ${u.user_id}, ${u.email}, ${sql.json({ items })}, ${"weekly:" + u.user_id + ":" + new Date().toISOString().slice(0, 10)}) as id`;
        if (q[0]?.id) out.weekly_queued++;
      }
    }

    // 3) the mail queue
    const q = await sql`
      select q.id, q.type, q.email_to, q.data,
             coalesce(q.user_id, (select u.id from auth.users u where lower(u.email) = q.email_to limit 1)) as uid
      from public.pp_email_queue q where q.status = 'pending' order by q.created_at limit 30`;
    out.queue = q.length;
    for (const r of q) {
      try {
        let unsubUrl = "";
        if (MARKETING.has(r.type) && r.uid) {
          const pr = await sql`insert into public.pp_email_prefs (user_id) values (${r.uid}) on conflict (user_id) do update set user_id = excluded.user_id returning token, marketing_off`;
          if (pr[0]?.marketing_off && !r.data?.test) { await sql`update public.pp_email_queue set status = 'skipped', error_message = 'unsubscribed' where id = ${r.id}`; out.skipped++; continue; }
          unsubUrl = `${self}?unsub=${pr[0].token}`;
        }
        const m = renderQueued(r.type, r.data || {}, site, links, unsubUrl);
        if (!m) { await sql`update public.pp_email_queue set status = 'failed', error_message = 'unknown type' where id = ${r.id}`; out.failed++; continue; }
        if (dry) continue;
        const from = MARKETING.has(r.type) ? fromMkt : SUPPORT_TYPES.has(r.type) ? fromSupport : fromAlert;
        const extra: Any = {};
        if (SUPPORT_TYPES.has(r.type)) extra.replyTo = { email: parseFrom(fromSupport).email };
        if (unsubUrl) extra.headers = { "List-Unsubscribe": `<${unsubUrl}>`, "List-Unsubscribe-Post": "List-Unsubscribe=One-Click" };
        const s = await send(from, r.email_to, m, r.type.replace(/_/g, "-"), extra);
        if (s.ok) { await sql`update public.pp_email_queue set status = 'sent', sent_at = now(), provider_message_id = ${s.id!}, error_message = null where id = ${r.id}`; out.sent++; }
        else { await sql`update public.pp_email_queue set status = 'failed', error_message = ${s.err!} where id = ${r.id}`; out.failed++; }
      } catch (e) {
        await sql`update public.pp_email_queue set status = 'failed', error_message = ${String(e).slice(0, 300)} where id = ${r.id}`; out.failed++;
      }
    }
  } finally {
    await sql.end({ timeout: 2 });
  }
  return new Response(JSON.stringify(out), { headers: { "Content-Type": "application/json" } });
});
